&lt;p&gt;&lt;code&gt;&lt;/code&gt;`js&lt;br&gt;
import { NavLink } from 'react-router-dom';&lt;br&gt;
import linkedinData from '../apis/mylinkedin.json';&lt;/p&gt;

&lt;p&gt;export default function ContactList() { &lt;br&gt;
    const activeState = ({ isActive }) =&amp;gt; {&lt;br&gt;
        return {&lt;br&gt;
          color: isActive ? "rgb(59 130 246)" : "",&lt;br&gt;
          borderLeft: isActive ? '3px solid rgb(59 130 246)' : ""&lt;br&gt;
        };&lt;br&gt;
      };&lt;/p&gt;

&lt;pre class="highlight plaintext"&gt;&lt;code&gt;const names = linkedinData.map((name)=&amp;gt; (
        &amp;lt;NavLink key={name.id} className="p-2 my-3 block font-raleway hover:bg-blue-300/20 transition-all rounded-xl" style={activeState} to={`profile/${name.id}`}&amp;gt;
          &amp;lt;span&amp;gt;{name.name}&amp;lt;/span&amp;gt;
        &amp;lt;/NavLink&amp;gt;
    ))
&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;return (&lt;br&gt;
    &amp;lt;&amp;gt;&lt;br&gt;
        &lt;br&gt;
            {names}&lt;br&gt;
        &lt;br&gt;
    &amp;lt;/&amp;gt;&lt;br&gt;
  )&lt;br&gt;
}&lt;br&gt;
`&lt;code&gt;&lt;/code&gt;&lt;/p&gt;

&lt;p&gt;What we are doing here is simply mapping through the arrays of object data and returning all the names in an anchor tag.&lt;/p&gt;

